INSERT INTO `galaxy_proxy` VALUES (19, 'httpResponseTimeMap', '/npm/httpResponseTimeMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(http_response_latency_ms)) AS http_response_latency,  <#if parameter.country?default(\'\')?trim? length gt 0> server_province AS server_province, <#if parameter.region?default(\'\')?trim? length gt 0> server_region AS server_region, </#if> </#if> server_country AS server_country  FROM tsg_base_country_city WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'HTTP\'  <#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.region?default(\'\')?trim? length gt 0> AND server_region != \'\' AND server_province = \'${parameter.region}\' AND server_country = \'${parameter.country}\' <#else> AND server_province != \'\' AND server_country = \'${parameter.country}\' </#if> <#else>  AND server_country != \'\' </#if>   GROUP BY server_country <#if parameter.country?default(\'\')?trim? length gt 0>   ,server_province <#if parameter.region?default(\'\')?trim? length gt 0> ,server_region  </#if> </#if> ORDER BY http_response_latency DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'var countryCodeMap = {\"Private IP\":\"CN\",\"Afghanistan\":\"AF\",\"Albania\":\"AL\",\"Algeria\":\"DZ\",\"American Samoa\":\"AS\",\"Andorra\":\"AD\",\"Angola\":\"AO\",\"Anguilla\":\"AI\",\"Antarctica\":\"AQ\",\"Antigua and Barbuda\":\"AG\",\"Argentina\":\"AR\",\"Armenia\":\"AM\",\"Aruba\":\"AW\",\"Australia\":\"AU\",\"Austria\":\"AT\",\"Azerbaijan\":\"AZ\",\"Bahamas (the)\":\"BS\",\"Bahrain\":\"BH\",\"Bangladesh\":\"BD\",\"Barbados\":\"BB\",\"Belarus\":\"BY\",\"Bel