kie\":\"PL-18\",\"Podlaskie\":\"PL-20\",\"Pomorskie\":\"PL-22\",\"Slaskie\":\"PL-24\",\"Swietokrzyskie\":\"PL-26\",\"Warminsko-mazurskie\":\"PL-28\",\"Wielkopolskie\":\"PL-30\",\"Zachodniopomorskie\":\"PL-32\"},\"PM\":{\"Saint Pierre and Miquelon\":\"\"},\"PN\":{\"Pitcairn\":\"\"}};\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverProvince){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverProvince];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:12:08', '2021-11-16 12:04:18', 1, '');
INSERT INTO `galaxy_proxy` VALUES (21, 'packetLossMap', '/npm/packetLossMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(SUM(common_c2s_tcp_lostlen +  common_s2c_tcp_lostlen)/SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen),4) AS sequence_gap_loss_percent,  <#if parameter.country?default(\'\')?trim? length gt 0> server_province AS server_province, <#if parameter.region?default(\'\')?trim? length gt 0> server_region AS server_region, </#if> </#if> server_country AS server_country   FROM tsg_base_country_city WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\',\'IPv6_TCP\')   <#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.region?default(\'\')?trim? length gt 0> AND server_region != \'\' AND server_province = \'${parameter.region}\' AND server_country = \'${parameter.country}\' <#else> AND server_province != \'\' AND server_country = \'${parameter.country}\' </#if> <#else>  AND server_country != \'\' </#if>  GROUP BY server_country <#if parameter.country?default(\'\')?trim? length gt 0>   ,server_province <#if parameter.region?default(\'\')?trim? length gt 0> ,server_region  </#if> </#if> ORDER BY sequence_gap_loss_percent DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100)', 'var countryCodeMap = {\"Private IP\":\"CN\",\"Afghanistan\":\"AF\",\"Albania\":\"AL\",\"Algeria\":\"DZ\",\"American Samoa\":\"AS\",\"Andorra\":\"AD\",\"Angola\":\"AO\",\"Anguilla\":\"AI\",\"Antarctica\":\"AQ\",\"Antigua and Barbuda\":\"AG\",\"Argentina\":\"AR\",\"Armenia\":\"AM\",\"Aruba\":\"AW\",\"Australia\":\"AU\",\"Austria\"