ubuskie\":\"PL-08\",\"Malopolskie\":\"PL-12\",\"Mazowieckie\":\"PL-14\",\"Opolskie\":\"PL-16\",\"Podkarpackie\":\"PL-18\",\"Podlaskie\":\"PL-20\",\"Pomorskie\":\"PL-22\",\"Slaskie\":\"PL-24\",\"Swietokrzyskie\":\"PL-26\",\"Warminsko-mazurskie\":\"PL-28\",\"Wielkopolskie\":\"PL-30\",\"Zachodniopomorskie\":\"PL-32\"},\"PM\":{\"Saint Pierre and Miquelon\":\"\"},\"PN\":{\"Pitcairn\":\"\"}};\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverProvince){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverProvince];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-23 18:14:48', '2021-11-16 12:04:08', 1, '');
INSERT INTO `galaxy_proxy` VALUES (23, 'ipFilter', '/entity/ip/filter', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'country\'>locate_country AS country,<#elseif parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'region\'>locate_region AS region,<#else>asn AS asn,</#if> count(*) AS count FROM ip WHERE 1=1 <#if parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'country\'>and locate_country != \'\'<#elseif parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'region\'>and locate_region!=\'\'<#else>and asn!=\'\'</#if> <#if parameter.country?default(\'\')?trim? length gt 0 > and locate_country = \'${parameter.country}\'</#if> <#if parameter.region?default(\'\')?trim? length gt 0 > and locate_region = \'${parameter.region}\' </#if><#if parameter.asn?default(\'\')?trim? length gt 0> AND asn in (<#list parameter.asn?split(\",\") as asn><#if !asn_has_next>\'${asn}\'<#else>\'${asn}\',</#if></#list>) </#if><#if parameter.ip?default(\'\')?trim? length gt 0 > and ip_addr = \'${parameter.ip}\'</#if> GROUP BY <#if parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'country\'>country<#elseif parameter.type?default(\'\')?trim? length gt 0&&parameter.type==\'region\'>region<#else>asn</#if> ORDER BY count DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0>limit ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (parameter.pageSize) {\r\n	if(!parameter.pageNo){\r\n		parameter.pageNo=0\r\n	}else{\r\n		parameter.pageNo=(parameter.pageNo-1)*parameter.pageSize\r\n	}\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-06-29 10:55:32', '2021-06-29 10:55:34', 1, '');
