\",\"Leon\":\"NI-LE\",\"Madriz\":\"NI-MD\",\"Managua\":\"NI-MN\",\"Masaya\":\"NI-MS\",\"Matagalpa\":\"NI-MT\",\"Nueva Segovia\":\"NI-NS\",\"Rio San Juan\":\"NI-SJ\",\"Rivas\":\"NI-RI\"},\"NL\":{\"Drenthe\":\"NL-DR\",\"Flevoland\":\"NL-FL\",\"Fryslan\":\"NL-FR\",\"Gelderland\":\"NL-GE\",\"Groningen\":\"NL-GR\",\"Limburg\":\"NL-LI\",\"Noord-Brabant\":\"NL-NB\",\"Noord-Holland\":\"NL-NH\",\"Overijssel\":\"NL-OV\",\"Utrecht\":\"NL-UT\",\"Zeeland\":\"NL-ZE\",\"Zuid-Holland\":\"NL-ZH\"},\"NO\":{\"Agder\":\"NO-42\",\"Innlandet\":\"NO-34\",\"More og Romsdal\":\"NO-15\",\"Nordland\":\"NO-18\",\"Oslo\":\"NO-03\",\"Rogaland\":\"NO-11\",\"Troms og Finnmark\":\"NO-54\",\"Trondelag\":\"NO-50\",\"Vestfold og Telemark\":\"NO-38\",\"Vestland\":\"NO-46\",\"Viken\":\"NO-30\"},\"NP\":{\"Bagmati\":\"NP-BA\",\"Bheri\":\"NP-BH\",\"Dhawalagiri\":\"NP-DH\",\"Gandaki\":\"NP-GA\",\"Janakpur\":\"NP-JA\",\"Karnali\":\"NP-KA\",\"Kosi\":\"NP-KO\",\"Lumbini\":\"NP-LU\",\"Mahakali\":\"NP-MA\",\"Mechi\":\"NP-ME\",\"Narayani\":\"NP-NA\",\"Rapti\":\"NP-RA\",\"Sagarmatha\":\"NP-SA\",\"Seti\":\"NP-SE\"},\"NR\":{\"Yaren\":\"NR-14\"},\"NU\":{\"Niue\":\"\"},\"NZ\":{\"Auckland\":\"NZ-AUK\",\"Bay of Plenty\":\"NZ-BOP\",\"Canterbury\":\"NZ-CAN\",\"Chatham Islands Territory\":\"NZ-CIT\",\"Gisborne\":\"NZ-GIS\",\"Hawke\'s Bay\":\"NZ-HKB\",\"Manawatu-Wanganui\":\"NZ-MWT\",\"Marlborough\":\"NZ-MBH\",\"Nelson\":\"NZ-NSN\",\"Northland\":\"NZ-NTL\",\"Otago\":\"NZ-OTA\",\"Southland\":\"NZ-STL\",\"Taranaki\":\"NZ-TKI\",\"Tasman\":\"NZ-TAS\",\"Waikato\":\"NZ-WKO\",\"Wellington\":\"NZ-WGN\",\"West Coast\":\"NZ-WTC\"},\"OM\":{\"Ad Dakhiliyah\":\"OM-DA\",\"Al Buraymi\":\"OM-BU\",\"Al Wusta\":\"OM-WU\",\"Az Zahirah\":\"OM-ZA\",\"Janub al Batinah\":\"OM-BJ\",\"Janub ash Sharqiyah\":\"OM-SJ\",\"Masqat\":\"OM-MA\",\"Musandam\":\"OM-MU\",\"Shamal al Batinah\":\"OM-BS\",\"Shamal ash Sharqiyah\":\"OM-SS\",\"Zufar\":\"OM-ZU\"},\"PA\":{\"Bocas del Toro\":\"PA-1\",\"Chiriqui\":\"PA-4\",\"Cocle\":\"PA-2\",\"Colon\":\"PA-3\",\"Darien