-COM\",\"Davao del Norte\":\"PH-DAV\",\"Davao del Sur\":\"PH-DAS\",\"Dinagat Islands\":\"PH-DIN\",\"Eastern Samar\":\"PH-EAS\",\"Guimaras\":\"PH-GUI\",\"Ifugao\":\"PH-IFU\",\"Ilocos Norte\":\"PH-ILN\",\"Ilocos Sur\":\"PH-ILS\",\"Iloilo\":\"PH-ILI\",\"Isabela\":\"PH-ISA\",\"Kalinga\":\"PH-KAL\",\"La Union\":\"PH-LUN\",\"Laguna\":\"PH-LAG\",\"Lanao del Norte\":\"PH-LAN\",\"Lanao del Sur\":\"PH-LAS\",\"Leyte\":\"PH-LEY\",\"Maguindanao\":\"PH-MAG\",\"Marinduque\":\"PH-MAD\",\"Masbate\":\"PH-MAS\",\"Mindoro Occidental\":\"PH-MDC\",\"Mindoro Oriental\":\"PH-MDR\",\"Misamis Occidental\":\"PH-MSC\",\"Misamis Oriental\":\"PH-MSR\",\"Mountain Province\":\"PH-MOU\",\"National Capital Region\":\"PH-00\",\"Negros Occidental\":\"PH-NEC\",\"Negros Oriental\":\"PH-NER\",\"Northern Samar\":\"PH-NSA\",\"Nueva Ecija\":\"PH-NUE\",\"Nueva Vizcaya\":\"PH-NUV\",\"Palawan\":\"PH-PLW\",\"Pampanga\":\"PH-PAM\",\"Pangasinan\":\"PH-PAN\",\"Quezon\":\"PH-QUE\",\"Quirino\":\"PH-QUI\",\"Rizal\":\"PH-RIZ\",\"Romblon\":\"PH-ROM\",\"Samar\":\"PH-WSA\",\"Sarangani\":\"PH-SAR\",\"Siquijor\":\"PH-SIG\",\"Sorsogon\":\"PH-SOR\",\"South Cotabato\":\"PH-SCO\",\"Southern Leyte\":\"PH-SLE\",\"Sultan Kudarat\":\"PH-SUK\",\"Sulu\":\"PH-SLU\",\"Surigao del Norte\":\"PH-SUN\",\"Surigao del Sur\":\"PH-SUR\",\"Tarlac\":\"PH-TAR\",\"Tawi-Tawi\":\"PH-TAW\",\"Zambales\":\"PH-ZMB\",\"Zamboanga Sibugay\":\"PH-ZSI\",\"Zamboanga del Norte\":\"PH-ZAN\",\"Zamboanga del Sur\":\"PH-ZAS\"},\"PK\":{\"Azad Jammu and Kashmir\":\"PK-JK\",\"Balochistan\":\"PK-BA\",\"Gilgit-Baltistan\":\"PK-GB\",\"Islamabad\":\"PK-IS\",\"Khyber Pakhtunkhwa\":\"PK-KP\",\"Punjab\":\"PK-PB\",\"Sindh\":\"PK-SD\"},\"PL\":{\"Dolnoslaskie\":\"PL-02\",\"Kujawsko-pomorskie\":\"PL-04\",\"Lodzkie\":\"PL-10\",\"Lubelskie\":\"PL-06\",\"Lubuskie\":\"PL-08\",\"Malopolskie\":\"PL-12\",\"Mazowieckie\":\"PL-14\",\"Opolskie\":\"PL-16\",\"Podkarpackie\":\"PL-18\",\"Podlaskie\":\"PL-20\",\"Pomorskie\":\"PL-22\",\"Slaskie\":\"PL-24\",\"Swietokrzyskie\":\"PL-26\",\"Warminsko-mazurskie\":\"PL-28\",\"Wielkopolskie\":\"PL-30\",\"Zachodniopomorskie\":\"PL-32\"},\"PM\":{\"Saint Pierre and Miquelon\":\"\"},\"PN\":{\"Pitcairn\":\"\"}};\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverProvince){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverProvince];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-01 09:48:59', '2021-11-16 12:03:48', 1, '');
INSERT INTO `galaxy_proxy` VALUES (120, 'ipDetailSessions', '/entity/ip/detail/sessions', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(common_sessions)/${parameter.step*60}) AS session_rate FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY stat_time \",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\nfunction replaceStr(str){ \r\n str = str.toLowerCase();\r\n var reg = /\\b(\\w)|\\s(\\w)/g; \r\n return str.replace(reg,function(m){ \r\n  return m.toUpperCase()\r\n });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-28 10:29:49', 1, '');
INSERT INTO `galaxy_proxy` VALUES (121, 'ipDetailPackets', '/entity/ip/detail/packets', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(IF(common_client_ip = \'${parameter.ip}\', common_c2s_pkt_num, common_s2c_pkt_num))/${parameter.step*60}) AS packets_sent_rate, ROUND(SUM(IF(common_client_ip = \'${parameter.ip}\', common_s2c_pkt_num, common_c2s_pkt_num))/${parameter.step*60}) AS packets_received_rate , ROUND(SUM(common_c2s_pkt_num + common_s2c_pkt_num)/${parameter.step*60}) AS packets_rate FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_client_ip = \'${parameter.ip}\' OR common_server_ip = \'${parameter.ip}\') GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			var index = key.indexOf(\"_\")\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-28 10:31:53', 1, '');
INSERT INTO `galaxy_proxy` VALUES (122, 'ipDetailThroughput', '/entity/ip/detail/throughput', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(IF(common_client_ip = \'${parameter.ip}\', common_c2s_byte_num, common_s2c_byte_num))/${parameter.step*60}) AS bytes_sent_rate, ROUND(SUM(IF(common_client_ip = \'${parameter.ip}\', common_s2c_byte_num, common_c2s_byte_num))/${parameter.step*60}) AS bytes_received_rate , ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/${parameter.step*60}) AS bytes_rate FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_client_ip = \'${parameter.ip}\' OR common_server_ip = \'${parameter.ip}\') GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			var index = key.indexOf(\"_\")\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-30 02:56:56', 1, '');
INSERT INTO `galaxy_proxy` VALUES (123, 'ipDetailActiveClientIP', '/entity/ip/detail/activeClientIP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT IF(common_client_ip = \'${parameter.ip}\', common_server_ip, common_client_ip) AS ip, SUM(common_sessions) as sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip = \'${parameter.ip}\') GROUP BY ip ORDER BY ${parameter.order} DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-01 09:48:59', '2021-09-29 07:55:33', 1, '');
INSERT INTO `galaxy_proxy` VALUES (124, 'ipDetailTopDomains', '/entity/ip/detail/topDomains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain AS domain, SUM(common_sessions) AS sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(domain)  AND (common_client_ip = \'${parameter.ip}\' or common_server_ip = \'${parameter.ip}\')  GROUP BY domain ORDER BY ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-01 09:48:59', '2021-09-24 09:04:45', 1, '');
INSERT INTO `galaxy_proxy` VALUES (125, 'ipDetailTopAPP', '/entity/ip/detail/topAPP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_app_label AS app , SUM(common_sessions) AS sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) AND (common_client_ip = \'${parameter.ip}\' or common_server_ip = \'${parameter.ip}\')  GROUP BY app ORDER BY ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-01 09:48:59', '2021-09-28 06:12:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (126, 'ipDetailAppRtt', '/entity/ip/detail/appRtt', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time,     common_app_label AS app_id,  ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM     tsg_base_metrics WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND common_app_label in (         SELECT             common_app_label         FROM             tsg_base_metrics         WHERE             common_recv_time > ${parameter.startTime}             AND common_recv_time < ${parameter.endTime}             AND <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>             AND notEmpty(common_app_label)         GROUP BY             common_app_label         ORDER BY             AVG(common_establish_latency_ms) DESC         LIMIT 10         ) GROUP BY     stat_time,     common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (127, 'ipDetailAppHttpResponseTime', '/entity/ip/detail/appHttpResponseTime', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, common_app_label AS app_id, ROUND(AVG(http_response_latency_ms)) AS http_response_latency FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if> AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG(http_response_latency_ms) DESC LIMIT 10 ) GROUP BY stat_time, common_app_label limit 10\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (128, 'ipDetailAppSSLHandshakeTime', '/entity/ip/detail/appSSLHandshakeTime', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, common_app_label AS app_id, ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if> AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG(ssl_con_latency_ms) DESC LIMIT 10 ) GROUP BY stat_time, common_app_label LIMIT 10\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (129, 'ipDetailAppPacketLoss', '/entity/ip/detail/appPacketLoss', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time,common_app_label AS common_app_label,ROUND(AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)),4) AS sequence_gap_loss_percent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label in ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip  = \'${parameter.ip}\' AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)) DESC LIMIT 10 ) GROUP BY stat_time,common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"common_app_label\";\r\n		var valueName=\"sequence_gap_loss_percent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n        o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-10-08 06:11:29', 1, '');
INSERT INTO `galaxy_proxy` VALUES (130, 'ipDetailAppPacketRetrans', '/entity/ip/detail/appPacketRetrans', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time, common_app_label AS common_app_label,ROUND(AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)),4) AS pkt_retrans_percent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label in ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip  = \'${parameter.ip}\' AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)) DESC LIMIT 10 ) GROUP BY stat_time,common_app_label\",\r\n	\"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"common_app_label\";\r\n		var valueName=\"pkt_retrans_percent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n        o.result.sort(sortByAvg);	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-10-08 06:12:27', 1, '');
INSERT INTO `galaxy_proxy` VALUES (131, 'ipDetailDomainRtt', '/entity/ip/detail/domainRtt', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time,     domain AS domain,     ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM     tsg_base_metrics WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND domain in (         SELECT             domain         FROM             tsg_base_metrics         WHERE             common_recv_time > ${parameter.startTime}             AND common_recv_time < ${parameter.endTime}             AND     <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>         AND notEmpty(domain)         GROUP BY             domain         ORDER BY             AVG(common_establish_latency_ms) DESC         LIMIT 10         ) GROUP BY     stat_time,     domain\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"domain\";\r\n		var valueName=\"establish_latency\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (132, 'ipDetailDomainHttpResponseTime', '/entity/ip/detail/domainHttpResponseTime', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time,     domain AS domain,     ROUND(AVG(http_response_latency_ms)) AS http_response_latency FROM     tsg_base_metrics WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND domain in (         SELECT             domain         FROM             tsg_base_metrics         WHERE             common_recv_time > ${parameter.startTime}             AND common_recv_time < ${parameter.endTime}             AND   <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if>       AND notEmpty(domain)         GROUP BY             domain         ORDER BY             AVG(http_response_latency_ms) DESC         LIMIT 10         ) GROUP BY     stat_time,     domain limit 10\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"domain\";\r\n		var valueName=\"http_response_latency\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
