n = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (141, 'entityFilter', '/entity/filter', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.column?default(\'\')?trim? length gt 0> ${parameter.column} AS name </#if>, count(*) AS count FROM <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'>domain <#else> app </#if> WHERE 1=1 <#if parameter.q?default(\'\')?trim? length gt 0>and ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> GROUP BY name ORDER BY count DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0>limit ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (parameter.pageSize) {\r\n	if(!parameter.pageNo){\r\n		parameter.pageNo=0\r\n	}else{\r\n		parameter.pageNo=(parameter.pageNo-1)*parameter.pageSize\r\n	}\r\n}\r\nif(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nif(parameter.q){\r\n       var q = parameter.q\r\n       var arr=[]\r\n       q = q.replace(/Unknown/ig,\"\")\r\n       if(q.match(/ip_addr/ig)){\r\n           arr = q.split(/ip_addr/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"ip_addr\")\r\n       }\r\n       if(q.match(/domain_name/ig)){\r\n           arr = q.split(/domain_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"domain_name\")\r\n       }\r\n        if(q.match(/app_name/ig)){\r\n           arr = q.split(/app_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"app_name\")\r\n       }\r\n       parameter.q = q\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n                                if(!pojo[key]){\r\n                                    pojo[key] = \"Unknown\"\r\n                                }\r\n                                tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-27 13:51:33', '2021-07-27 13:51:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (142, 'appDetailCount', '/entity/app/detail/count', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time, count(distinct(common_client_ip)) AS count FROM     tsg_base_metrics WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime} 	AND     common_app_label     = \'${parameter.app}\' GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\nparameter.start = parameter.startTime;\r\nparameter.end = parameter.endTime;\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length===0){\r\n	var data1={\r\n	\"stat_time\":parameter.start,\r\n	\"count\":0\r\n	};\r\n	var data2={\r\n	\"stat_time\":parameter.end,\r\n	\"count\":0\r\n	};\r\n	list.add(data1);\r\n	list.add(data2);\r\n	}\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			aggregation.total = sumValue;\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = \"visits\";\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-28 10:02:00', 1, '');
INSERT INTO `galaxy_proxy` VALUES (143, 'appDetailCountLine', '/entity/app/detail/countLine', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time, count(distinct(common_client_ip)) AS count FROM     tsg_base_metrics WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime} 	AND     common_app_label     = \'${parameter.appId?js_string}\' GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (144, 'domainDetailCount', '/entity/domain/detail/count', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT  TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, count(distinct(common_client_ip)) AS visits FROM     tsg_base_metrics WHERE common_recv_time > ${parameter.startTime}  AND common_recv_time < ${parameter.endTime}  AND domain  = \'${parameter.domain}\' GROUP BY  stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\nparameter.start = parameter.startTime;\r\nparameter.end = parameter.endTime;\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length===0){\r\n	var data1={\r\n	\"stat_time\":parameter.start,\r\n	\"visits\":0\r\n	};\r\n	var data2={\r\n	\"stat_time\":parameter.end,\r\n	\"visits\":0\r\n	};\r\n	list.add(data1);\r\n	list.add(data2);\r\n	}\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			aggregation.total = sumValue;\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-28 10:02:33', 1, '');
INSERT INTO `galaxy_proxy` VALUES (145, 'domainDetailCountLine', '/entity/domain/detail/countLine', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time,     count(distinct(common_client_ip)) AS count FROM     tsg_base_metrics WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND     domain           = \'${parameter.domain}\' GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (146, 'entityList', '/entity/list', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip_addr AS ip, locate_country AS country, locate_region AS region, asn AS asn <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'> domain_name AS domain_name, category_group AS category_group, category_name AS category_name, reputation_level AS reputation_level, reputation_score AS reputation_score <#else> app_id AS app_id, app_name AS app_name, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk </#if> FROM <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'> domain <#else> app </#if> WHERE 1=1 <#if parameter.q?default(\'\')?trim? length gt 0>and ${parameter.q} </#if> ORDER BY update_time DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0>limit ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (parameter.pageSize) {\r\n	if(!parameter.pageNo){\r\n		parameter.pageNo=0\r\n	}else{\r\n		parameter.pageNo=(parameter.pageNo-1)*parameter.pageSize\r\n	}\r\n}\r\nif(parameter.q){\r\n       var q = parameter.q\r\n       var arr=[]\r\n       q = q.replace(/Unknown/ig,\"\")\r\n       if(q.match(/ip_addr/ig)){\r\n           arr = q.split(/ip_addr/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"ip_addr\")\r\n       }\r\n       if(q.match(/domain_name/ig)){\r\n           arr = q.split(/domain_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"domain_name\")\r\n       }\r\n        if(q.match(/app_name/ig)){\r\n           arr = q.split(/app_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"app_name\")\r\n       }\r\n       parameter.q = q\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n                        var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-27 16:38:54', '2021-07-27 16:38:59', 1, '');
INSERT INTO `galaxy_proxy` VALUES (147, 'entityTotal', '/entity/total', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(*) AS count FROM <#if parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'ip\'> ip <#elseif parameter.from?default(\'\')?trim? length gt 0&&parameter.from==\'domain\'> domain <#else> app </#if>  WHERE 1=1 <#if parameter.q?default(\'\')?trim? length gt 0>and ${parameter.q} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.q){\r\n       var q = parameter.q\r\n       var arr=[]\r\n       q = q.replace(/Unknown/ig,\"\")\r\n       if(q.match(/ip_addr/ig)){\r\n           arr = q.split(/ip_addr/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"ip_addr\")\r\n       }\r\n       if(q.match(/domain_name/ig)){\r\n           arr = q.split(/domain_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"domain_name\")\r\n       }\r\n        if(q.match(/app_name/ig)){\r\n           arr = q.split(/app_name/i)\r\n           var index1 = arr[1].indexOf(\"\'\")\r\n           var index = arr[1].slice(index1+1).indexOf(\"\'\")\r\n           arr[1] = arr[1].slice(0,(index1+index+1))+\"%\"+arr[1].slice((index1+index+1))\r\n           arr[1] = arr[1].replace(\"=\",\" like\")\r\n           q = arr.join(\"app_name\")\r\n       }\r\n       parameter.q = q\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-27 16:39:23', '2021-07-27 16:39:26', 1, '');
INSERT INTO `galaxy_proxy` VALUES (148, 'entityIpDetailServerIPCountLine', '/entity/ip/detail/serverIPCountLine', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time,<#if parameter.serverIP?default(\'\')?trim? length gt 0> count(distinct(common_server_ip)) AS server_ip_count <#else> count(distinct(common_client_ip)) as client_ip_count</#if> FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND     common_recv_time  < ${parameter.endTime} AND <#if parameter.serverIP?default(\'\')?trim? length gt 0> common_server_ip = \'${parameter.serverIP}\' <#else> common_client_ip = \'${parameter.clientIP}\' </#if> GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push(pojo[key]);\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-08-13 18:27:25', '2021-08-13 18:27:28', 1, '');
INSERT INTO `galaxy_proxy` VALUES (149, 'entityIpDetailServerIPCount', '/entity/ip/detail/serverIPCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time,count(distinct(common_server_ip)) AS server_ip_count FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_client_ip  = \'${parameter.ip}\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\nparameter.start = parameter.startTime;\r\nparameter.end = parameter.endTime;\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length===0){\r\n	var data1={\r\n	\"stat_time\":parameter.start,\r\n	\"server_ip_count\":0\r\n	};\r\n	var data2={\r\n	\"stat_time\":parameter.end,\r\n	\"server_ip_count\":0\r\n	};\r\n	list.add(data1);\r\n	list.add(data2);\r\n	}\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.total = sumValue ;\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			var index = key.lastIndexOf(\"_\");\r\n			var key1 = key.slice(0,index).replace(\"_\",\" \");\r\n			lineObj.legend = key1;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-08-13 18:28:49', '2021-09-28 09:53:15', 1, '');
INSERT INTO `galaxy_proxy` VALUES (150, 'entityRelationship', '/entity/relationship', 'v1', 'POST', '/cn/v1/entityExplorer', '{\"query\": {\"dataEngine\": \"AnalysisEngine\",\"queryType\": \"entityDetail\",\"dataSource\": \"entity_detail_<#if parameter.type==\'ip\'>ip<#elseif parameter.type==\'app\'>app<#else>domain</#if>_view\",\"parameters\": {\"limit\": <#if parameter.limit?default(\'\')?trim? length gt 0>${parameter.limit}<#else>10</#if>,\"sort\": [{\"type\": \"desc\",\"fieldKey\": \"lastTime\"}],\"match\": {\"condition\": [{\"type\": \"exactly\",\"fieldKey\": \"<#if parameter.type==\'ip\'>ip<#elseif parameter.type==\'app\'>app_name<#else>domain</#if>\",\"fieldValues\": [\"${parameter.q?js_string}\"]}]}}}}', '{}', '', 'function handlerResult(obj,data){\r\n	if(data!=null&&data!=undefined){\r\n        if(data.leaf!=null&&data.leaf!=undefined&&data.leaf.length>0){\r\n            for(var i in data.leaf){\r\n                handlerResult(obj,data.leaf[i]);\r\n            }\r\n        }else{\r\n            var node = {};\r\n            node.name = data.name;\r\n            node.type = data.type;\r\n            node.lastTime = data.last_time;\r\n\r\n            var link = {};\r\n            link.from = data.from;\r\n            link.to = data.to;\r\n\r\n            obj.result.links.push(link);\r\n            obj.result.nodes.push(node);\r\n        }\r\n    }\r\n}\r\n\r\nif(result.success){\r\n	if(parameter.format==1){\r\n		var o={};\r\n		o.resultType=\"relation\";\r\n		o.result={};\r\n		o.result.nodes=[];\r\n		o.result.links=[];\r\n		if(result.data!=undefined&&result.data!=null&&result.data.length>0){\r\n			handlerResult(o,result.data[0]);\r\n		}\r\n		result.data=o;\r\n		result.code=200;\r\n		result.msg = \"\";\r\n		result.message=null;\r\n		var jsonObj = {};\r\n		for(var name in result){       \r\n			jsonObj[name] = result[name];\r\n		}\r\n		result = JSON.stringify(jsonObj);\r\n	}else{\r\n		var o={};\r\n		if(result.data!=undefined&&result.data!=null&&result.data.length>0){\r\n			o.resultType=\"relationTree\";\r\n			o.result={};\r\n			o.result.type=result.data[0].type;\r\n			o.result.name=result.data[0].name;\r\n			o.result.leaf=result.data[0].leaf;\r\n		}\r\n		result.data=o;\r\n		result.code=200;\r\n		result.msg = \"\";\r\n		result.message=null;\r\n	}\r\n}', '2021-08-16 09:59:42', '2021-09-27 06:17:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (154, 'ipDetailBasicInfo', '/entity/ip/detail/basicInfo', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT asn AS asn,locate_country AS country,locate_region AS region,locate_longitude AS longitude,locate_latitude AS latitude,\'IDC, China Telecommunications Corporation\' AS asnOrg,\'220.181.32.0/20\' AS asnSubnet,\'China telecom\' AS isp,\'DNS PTR\' AS dnsPTR FROM ip WHERE ip_addr = \'${parameter.ip}\' LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	o.result=result.data[0];\r\n	if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-09-18 03:28:45', '2021-10-09 01:49:46', 1, '');
INSERT INTO `galaxy_proxy` VALUES (155, 'ipDetailPorts', '/entity/ip/detail/ports', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT substring(toString(rand()), 1, 4) AS port,common_schema_type AS protocol,\'Banner\' AS banner,now() AS utime FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime}  AND common_recv_time < ${parameter.endTime} AND (common_client_ip =\'${parameter.ip}\' OR common_server_ip = \'${parameter.ip}\') GROUP BY common_schema_type\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\nif(result.success){\r\n        var list = result.data;\r\n        	  \r\n        var o={};\r\n        o.resultType=\"table\";\r\n        o.result=list;\r\n        if(list.length == 0){\r\n            \r\n            var data1 = {\r\n                \"port\": \"80\",\r\n                \"protocol\": \"HTTP\",\r\n                \"banner\": \"Http/1.1 200 OK\\r\\nDate:2021-9-17 13:53:03\\r\\nServer: Apache\",\r\n                \"utime\": \"2021-9-17 13:53:37\"\r\n            };\r\n            var data2 = {\r\n                \"port\": \"443\",\r\n                \"protocol\": \"HTTPS\",\r\n                \"banner\": \"Http/1.1 200 OK\\r\\nDate:2021-9-17 13:53:03\\r\\nServer: Apache\",\r\n                \"utime\": \"2021-9-17 13:53:37\"\r\n            };\r\n            list.add(data1);\r\n            list.add(data2);\r\n        }\r\n        result.code=200;\r\n        result.data=o;\r\n        result.msg = result.message;\r\n        result.message=null;\r\n}', '2021-09-18 03:32:19', '2021-09-18 03:33:53', 1, '');
INSERT INTO `galaxy_proxy` VALUES (156, 'ipDetailDomains', '/entity/ip/detail/domains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime}  AND common_recv_time < ${parameter.endTime} AND (common_client_ip =\'${parameter.ip}\' OR common_server_ip = \'${parameter.ip}\') AND notEmpty(domain) GROUP BY domain  ORDER BY SUM(common_sessions) DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'if(result.success){\r\n    \r\n	var o={};\r\n	\r\n	var list = result.data;\r\n        var arr = new java.util.ArrayList();  \r\n        if(list.length > 0){\r\n            for(var i=0; i< list.length; i++){\r\n                var pojo = list[i];\r\n                arr.add(pojo[\"domain\"])  \r\n            }\r\n        }else{     \r\n            arr.add(\"baidu.com\");\r\n       	    arr.add(\"qq.com\");\r\n	    arr.add(\"taobao.com\");  \r\n        }\r\n        \r\n	o.resultType=\"array\"\r\n	o.result=arr;\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-09-18 03:33:58', '2021-09-18 03:35:33', 1, '');
INSERT INTO `galaxy_proxy` VALUES (157, 'ipDdetailServiceOverview', '/entity/ip/detail/serviceOverview', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(common_establish_latency_ms)) AS establish_latency_ms, ROUND(AVG(http_response_latency_ms)) AS http_response_latency_ms , ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency_ms , ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS sequence_gap_loss_percent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS pkt_retrans_percent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip = \'${parameter.ip}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'if(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	o.result=result.data[0];\r\n	if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-09-18 06:47:39', '2021-10-08 03:30:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (158, 'ipDetailOverallEstablishlatency', '/entity/ip/detail/overallEstablishlatency', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time,ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND  common_server_ip  = \'${parameter.ip}\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-09-18 06:49:27', '2021-10-08 03:32:13', 1, '');
