INSERT INTO `galaxy_proxy` VALUES (225, 'entityIndexTotal', '/entity/index/total', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> COUNT(DISTINCT(app_name)) AS all_count <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> COUNT(DISTINCT(domain_name)) AS all_count <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\"> COUNT(DISTINCT(ip_addr)) AS all_count </#if> FROM cn_entity WHERE entity_type=\'${parameter.entityType}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-15 09:00:12', '2021-12-15 09:00:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (226, 'entityIndexNew', '/entity/index/new', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> COUNT(DISTINCT(app_name)) AS new_count <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> COUNT(DISTINCT(domain_name)) AS new_count <#elseif parameter.entityType == \"ip\"> COUNT(DISTINCT(ip_addr)) AS new_count </#if> FROM cn_entity WHERE entity_type=\'${parameter.entityType}\' AND found_time >= ${parameter.startTime} AND found_time < ${parameter.endTime}\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-15 09:01:12', '2021-12-15 09:01:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (227, 'entityIndexActive', '/entity/index/active', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> COUNT(DISTINCT(app_name)) AS active_count <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> COUNT(DISTINCT(domain_name)) AS active_count <#elseif parameter.entityType == \"ip\"> COUNT(DISTINCT(ip_addr)) AS active_count </#if> FROM cn_entity WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-15 09:02:12', '2021-12-15 09:02:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (228, 'entityFilterCount', '/entity/filter/count', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count, <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> COUNT(DISTINCT(app_category)) AS category_distinct_count, COUNT(DISTINCT(app_subcategory)) AS subcategory_distinct_count, COUNT(DISTINCT(app_risk)) AS risk_distinct_count <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> COUNT(DISTINCT(domain_category_group)) AS category_group_distinct_count, COUNT(DISTINCT(domain_category)) AS category_distinct_count, COUNT(DISTINCT(domain_reputation_level)) AS reputation_level_distinct_count <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\"> COUNT(DISTINCT(ip_location_country)) AS country_distinct_count, COUNT(DISTINCT(ip_location_province)) AS province_distinct_count, COUNT(DISTINCT(ip_location_city)) AS city_distinct_count, COUNT(DISTINCT(ip_asn)) AS asn_distinct_count </#if> FROM cn_entity WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nif (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result=result.data[0];\r\n	var pojo = o.result;\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-15 09:03:12', '2021-12-15 09:03:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (229, 'entityFilterTop', '/entity/filter/top', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count, <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> ${parameter.column} AS name <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> ${parameter.column} AS name <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\"> ${parameter.column} AS name </#if> FROM cn_entity WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> GROUP BY name ORDER BY count DESC LIMIT ${parameter.top}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nif (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:04:12', '2021-12-15 09:04:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (230, 'entityListBasic', '/entity/list/basic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\">entity_type AS entity_type, app_name AS app_name, app_id AS app_id, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\">entity_type AS entity_type, domain_name AS domain_name, domain_category AS domain_category, domain_category_group AS domain_category_group, domain_reputation_score AS domain_reputation_score, domain_reputation_level AS domain_reputation_level <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\">entity_type AS entity_type, ip_addr AS ip_addr, ip_location_country AS ip_location_country, ip_location_province AS ip_location_province, ip_location_city AS ip_location_city, ip_asn AS ip_asn <#else>entity_type AS entity_type, ip_addr AS ip_addr, ip_location_country AS ip_location_country, ip_location_province AS ip_location_province, ip_location_city AS ip_location_city, ip_asn AS ip_asn, app_name AS app_name, app_id AS app_id, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk, domain_name AS domain_name, domain_category AS domain_category, domain_category_group AS domain_category_group, domain_reputation_score AS domain_reputation_score, domain_reputation_level AS domain_reputation_level </#if> FROM cn_entity WHERE update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.entityType?default(\'\')?trim? length gt 0> AND entity_type=\'${parameter.entityType}\' </#if>  <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> ORDER BY update_time DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0> LIMIT ${parameter.pageNo},${parameter.pageSize} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nif (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:05:12', '2021-12-15 09:05:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (231, 'entityListTraffic', '/entity/list/traffic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(common_c2s_byte_num)/ (${parameter.step}*60)) AS bytes_sent_rate, ROUND(SUM(common_s2c_byte_num)/ (${parameter.step}*60)) AS bytes_received_rate FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\"> AND (common_client_ip=\'${parameter.name}\' OR common_server_ip=\'${parameter.name}\') <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> AND domain=\'${parameter.name}\' <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> AND common_app_label=\'${parameter.name}\' </#if> GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key] + "";\r\n			aggregation.last = list[list.length - 1][key] + "";\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = Math.round(sumValue / list.length) + "";\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key] + "";\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-15 09:06:12', '2021-12-15 09:06:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (232, 'entityListAlertNum', '/entity/list/alertNum', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count FROM cn_alert WHERE entity_type = \'${parameter.entityType}\' AND entity_name = \'${parameter.name}\' AND start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:07:12', '2021-12-15 09:07:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (233, 'entityListDetectionNum', '/entity/list/detectionNum', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count FROM cn_security_event WHERE destination_type = \'${parameter.entityType}\' AND destination_name = \'${parameter.name}\' AND start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:08:12', '2021-12-15 09:08:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (234, 'trafficTopAppCategories', '/traffic/topAppCategories', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT app_category AS app_category, uniq(common_app_label) AS uniq_apps, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, SUM(common_sessions) AS sessions FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) AND notEmpty(app_category) GROUP BY app_category ORDER BY uniq_apps desc LIMIT ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-16 13:46:32', '2021-12-16 13:46:36', 1, '');
