INSERT INTO `galaxy_proxy` VALUES (240, 'cryptcyTrafficPercentage', '/cryptcy/trafficPercentage', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(isNull(${parameter.traffic!0}/nullif(SUM(common_c2s_byte_num + common_s2c_byte_num),0)),4) AS traffic_percentage FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {     parameter.endTime = nowTimestamp } if (!parameter.startTime) {     parameter.startTime = nowTimestamp - 10 * 60 *1000 } /*计算step,series最多显示100个点，单位：min*/ parameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);  parameter.endTime = \'toDateTime(\'+parameter.endTime+\')\'; parameter.startTime = \'toDateTime(\'+parameter.startTime+\')\'; if(parameter.ip){     var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');     var result = galaxyUtils.sendGalaxyRequest(\'/cryptcy/traffic\',\'GET\',parameter);     if(result.success){         var cryTraffic = result.data;         parameter.traffic = cryTraffic;     } }', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-19 13:50:32', '2021-12-19 13:50:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (241, 'entityDetailDomainBasic', '/entity/detail/domain/basic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain_category_group AS domain_category_group, domain_category AS domain_category, domain_reputation_level AS domain_reputation_level FROM cn_entity WHERE domain_name=\'${parameter.domain}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result=result.data[0];\r\n	var pojo = o.result;\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-29 12:50:32', '2021-12-29 12:50:36', 1, '');
