INSERT INTO `galaxy_proxy` VALUES (247, 'entityDetailIpAppCount', '/entity/detail/ip/appCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(distinct(common_app_label)) AS app_count FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_client_ip = \'${parameter.ip}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-29 12:56:32', '2021-12-29 12:56:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (248, 'entityDetailIpDomainCount', '/entity/detail/ip/domainCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(distinct(domain)) AS domain_count FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_client_ip = \'${parameter.ip}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-29 12:57:32', '2021-12-29 12:57:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (249, 'entityDetailIpSessions', '/entity/detail/ip/sessions', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(common_sessions)/${parameter.step*60}) AS session_rate FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\nfunction replaceStr(str){ \r\n str = str.toLowerCase();\r\n var reg = /\\b(\\w)|\\s(\\w)/g; \r\n return str.replace(reg,function(m){ \r\n  return m.toUpperCase()\r\n });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-29 12:57:32', '2021-12-29 12:57:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (250, 'entityDetailIpPackets', '/entity/detail/ip/packets', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(IF(common_client_ip=\'${parameter.ip}\', common_c2s_pkt_num, common_s2c_pkt_num))/${parameter.step*60}) AS packets_sent_rate, ROUND(SUM(IF(common_client_ip=\'${parameter.ip}\', common_s2c_pkt_num, common_c2s_pkt_num))/${parameter.step*60}) AS packets_received_rate FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\nfunction replaceStr(str){ \r\n str = str.toLowerCase();\r\n var reg = /\\b(\\w)|\\s(\\w)/g; \r\n return str.replace(reg,function(m){ \r\n  return m.toUpperCase()\r\n });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-29 12:58:32', '2021-12-29 12:58:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (251, 'entityDetailIpBytes', '/entity/detail/ip/bytes', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(IF(common_client_ip=\'${parameter.ip}\', common_c2s_byte_num, common_s2c_byte_num))/${parameter.step*60}) AS bytes_sent_rate, ROUND(SUM(IF(common_client_ip=\'${parameter.ip}\', common_s2c_byte_num, common_c2s_byte_num))/${parameter.step*60}) AS bytes_received_rate FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\nfunction replaceStr(str){ \r\n str = str.toLowerCase();\r\n var reg = /\\b(\\w)|\\s(\\w)/g; \r\n return str.replace(reg,function(m){ \r\n  return m.toUpperCase()\r\n });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"stat_time\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-29 13:00:32', '2021-12-29 13:00:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (252, 'entityDetailIpActiveClientIP', '/entity/detail/ip/activeClientIP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_client_ip AS client_ip, SUM(common_sessions) as sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip = \'${parameter.ip}\' GROUP BY client_ip ORDER BY ${parameter.order} DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-29 13:01:32', '2021-12-29 13:01:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (253, 'entityDetailIpTopDomains', '/entity/detail/ip/topDomains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain AS domain, SUM(common_sessions) AS sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(domain) AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY domain ORDER BY ${parameter.order} DESC limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-29 13:02:32', '2021-12-29 13:02:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (254, 'entityDetailIpTopAPP', '/entity/detail/ip/topAPP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_app_label AS app_label, SUM(common_sessions) AS sessions, SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY app_label ORDER BY ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-29 13:03:32', '2021-12-29 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (255, 'entityDetailIpServiceOverview', '/entity/detail/ip/serviceOverview', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(common_establish_latency_ms)) AS establish_latency_ms, ROUND(AVG(http_response_lantency_ms)) AS http_response_lantency_ms, ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency_ms, ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS sequence_gap_loss_percent, ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS pkt_retrans_percent FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip = \'${parameter.ip}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result=result.data[0];\r\n	var pojo = o.result;\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-29 13:03:32', '2021-12-29 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (256, 'entityDetailIpOverallEstablishlatency', '/entity/detail/ip/overallEstablishlatency', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND (common_server_ip = \'${parameter.ip}\' OR common_client_ip=\'${parameter.ip}\') GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n for(var i in list){\r\n        var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-29 13:03:32', '2021-12-29 13:03:36', 1, '');
