main\";\r\n		var valueName=\"sslConLatency\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (324, 'entityDetailAppDomainPacketLoss', '/entity/detail/app/domainPacketLoss', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time, domain AS domain, ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen),4) AS sequence_gap_loss_percent FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND domain in ( SELECT domain FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label = \'${parameter.appName}\' AND notEmpty(domain) GROUP BY domain ORDER BY AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)) DESC LIMIT 10 ) GROUP BY stat_time, domain\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		var fields={};\r\n		var field = \"domain\";\r\n		var valueName=\"sequenceGapLossPercent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (325, 'entityDetailAppDomainPacketRetrans', '/entity/detail/app/domainPacketRetrans', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') as stat_time, domain AS domain, ROUND(AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)),4) AS pkt_retrans_percent FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND domain in ( SELECT domain FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label = \'${parameter.appName}\' AND notEmpty(domain) GROUP BY domain ORDER BY AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)) DESC LIMIT 10 ) GROUP BY stat_time, domain\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		var fields={};\r\n		var field = \"domain\";\r\n		var valueName=\"pktRetransPercent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[valueName]-a[valueName];\r\n			});\r\n			aggregation.max = list[0][valueName];\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (326, 'entityDetailAppDomainlinkVisual', '/entity/detail/app/linkVisual', 'v1', 'GET', '/', '{\r\n    \"query\": \"(SELECT common_ingress_link_id AS linkID,\'in\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_ingress_link_id != 0 AND common_egress_link_id !=0 AND common_app_label = \'${parameter.appName}\' GROUP BY linkID) UNION ALL (SELECT common_egress_link_id AS linkID,\'out\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_ingress_link_id != 0 AND common_egress_link_id !=0 AND common_app_label = \'${parameter.appName}\' GROUP BY linkID)\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 10 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (327, 'entityDetailOverviewAppTraffic', '/entity/detail/overview/app/traffic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/ ${parameter.step*60}) AS bytes_rate, ROUND(SUM(common_c2s_byte_num)/${parameter.step*60}) AS bytes_sent_rate, ROUND(SUM(common_s2c_byte_num)/${parameter.step*60}) AS bytes_received_rate FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label = \'${parameter.appName}\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key] + "";\r\n			aggregation.last = list[list.length - 1][key] + "";\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = Math.round(sumValue / list.length) + "";\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key] + "";\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-31 13:03:32', '2021-12-31 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (328, 'entityDetailOverviewAppRelation', '/entity/detail/overview/app/relation', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(domain)) AS domain_count, COUNT(DISTINCT(common_server_ip)) AS ip_count FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label=\'${parameter.appName}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result=result.data[0];\r\n	var pojo = o.result;\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-31 13:03:32', '2021-12-31 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (329, 'entityDetailOverviewAppAlert', '/entity/detail/overview/app/alert', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT start_time AS start_time, alert_name AS alert_name, alert_severity AS alert_severity, alert_type AS alert_type FROM cn_alert WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} AND entity_type = \'app\' AND entity_name = \'${parameter.appName}\' GROUP BY start_time, alert_name, alert_severity, alert_type ORDER BY start_time DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-31 13:03:32', '2021-12-31 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (330, 'entityDetailOverviewAppSecurity', '/entity/detail/overview/app/security', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT start_time AS start_time, source_name AS source_name, destination_name AS destination_name, security_severity AS security_severity, security_type AS security_type, security_category AS security_category FROM cn_security_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} AND destination_type=\'app\' AND destination_name=\'${parameter.appName}\' GROUP BY start_time, source_name, destination_name, security_severity, security_type, security_category ORDER BY start_time DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType="table";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-31 13:03:32', '2021-12-31 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (331, 'entityDetailOverviewDomainBasic', '/entity/detail/overview/domain/basic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain_category AS domain_category, domain_category_group AS domain_category_group, domain_reputation_score AS domain_reputation_score, domain_whois_address AS domain_whois_address, domain_whois_org AS domain_whois_org, \'XX is the most popular free instant messaging....\' AS domain_description FROM cn_entity WHERE update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} AND domain_name=\'${parameter.domain}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n	if(o.result.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-31 13:03:32', '2021-12-31 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (332, 'entityDetailOverviewDomainTraffic', '/entity/detail/overview/domain/traffic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}M\',\'zero\') AS stat_time, ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/ ${parameter.step*60}) AS bytes_rate, ROUND(SUM(common_c2s_byte_num)/ ${parameter.step*60}) AS bytes_sent_rate, ROUND(SUM(common_s2c_byte_num)/ ${parameter.step*60}) AS bytes_received_rate FROM cn_record WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND domain=\'${parameter.domain}\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key] + "";\r\n			aggregation.last = list[list.length - 1][key] + "";\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = Math.round(sumValue / list.length) + "";\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key] + "";\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-31 13:03:32', '2021-12-31 13:03:36', 1, '');
