INSERT INTO `galaxy_proxy` VALUES (343, 'entityListTotal', '/entity/list/total', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(*) AS count FROM cn_entity WHERE 1=1 <#if parameter.startTime?default(\'\')?trim? length gt 0> AND update_time >= ${parameter.startTime} </#if> <#if parameter.endTime?default(\'\')?trim? length gt 0> AND update_time < ${parameter.endTime} </#if> <#if parameter.entityType?default(\'\')?trim? length gt 0> AND entity_type=\'${parameter.entityType}\' </#if>  <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nif (!parameter.endTime) {\r\n    parameter.endTime = nowTimestamp\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = nowTimestamp - 5 * 60 *1000\r\n}\r\n/*计算step,series最多显示100个点，单位：min*/\r\nparameter.step = Math.ceil((parameter.endTime-parameter.startTime)/6000/100);', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-1-5 09:06:12', '2022-1-5 09:06:16', 1, '');
